head.script:
scwin.timer = null;

scwin.onpageload = function () {
    let arr = [
        { "name" : "홍길동", "col" : "S" },
        { "name" : "김철수", "col" : "J" },
        { "name" : "이영희", "col" : "" }
    ];
    dlt_a.setJSON(arr);
    dlt_b.setJSON(arr);

    // 클릭(더블클릭 포함) 400ms 후 목록 상태 출력 (capture 단계)
    document.addEventListener("click", function () {
        if (scwin.timer) {
            clearTimeout(scwin.timer);
        }
        scwin.timer = setTimeout(scwin.reportList, 400);
    }, true);

    // Enter / Tab 으로 편집 종료 300ms 후 Cell 값 출력 (capture 단계)
    document.addEventListener("keydown", scwin.document_keydownCapture, true);
};

// 비교 대상 그리드 목록
scwin.getGrdList = function () {
    return [ { "grd" : grd_a, "dlt" : dlt_a, "name" : "A" }, { "grd" : grd_b, "dlt" : dlt_b, "name" : "B" } ];
};

// 편집 중인 col Cell 에서 Enter / Tab 입력 시 편집 종료 후 Cell 값과 표시값 출력
scwin.document_keydownCapture = function (e) {
    if (e.key !== "Enter" && e.key !== "Tab") {
        return;
    }
    let arrGrd = scwin.getGrdList();
    for (let i = 0; i < arrGrd.length; i++) {
        let item = arrGrd[i];
        if (!item.grd.isEditing() || item.grd.getFocusedColumnID() !== "col") {
            continue;
        }
        let rowIndex = item.grd.getFocusedRowIndex();
        let colIndex = item.grd.getFocusedColumnIndex();
        let key = e.key;
        setTimeout(function () {
            let td = document.getElementById(item.grd.id + "_cell_" + rowIndex + "_" + colIndex);
            scwin.setReturnValue("[" + item.name + "] " + key + " 후 Cell 값 : '" + item.dlt.getCellData(rowIndex, "col") + "' / 표시값 : '" + (td ? td.textContent.trim() : "") + "'");
        }, 300);
    }
};

// 편집 중인 col Cell 의 목록이 열려 있으면 표시 항목 수 / 선택 대상 출력
scwin.reportList = function () {
    scwin.timer = null;
    let arrGrd = scwin.getGrdList();
    for (let i = 0; i < arrGrd.length; i++) {
        let grd = arrGrd[i].grd;
        if (!grd.isEditing() || grd.getFocusedColumnID() !== "col") {
            continue;
        }
        let rowIndex = grd.getFocusedRowIndex();
        let td = document.getElementById(grd.id + "_cell_" + rowIndex + "_" + grd.getFocusedColumnIndex());
        let editorEl = td ? td.querySelector("[role='combobox']") : null;
        if (!editorEl) {
            continue;
        }
        let arrCell = Array.prototype.filter.call(document.querySelectorAll("[id^='" + editorEl.id + "_itemTable_']"), function (cell) {
            return /_itemTable_\d+$/.test(cell.id) && cell.getClientRects().length > 0;
        });
        if (arrCell.length === 0) {
            continue;
        }
        let marked = "없음";
        for (let j = 0; j < arrCell.length; j++) {
            if (/_col_over/.test(arrCell[j].className)) {
                marked = "index " + j + " '" + arrCell[j].textContent + "'";
                break;
            }
        }
        scwin.setReturnValue("[" + arrGrd[i].name + "] " + arrGrd[i].dlt.getCellData(rowIndex, "name") + " 행 목록 표시 (항목 " + arrCell.length + "개) / 선택 대상 : " + marked);
    }
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
